// ============================================================
// Vormerkerliste als lesbare HTML-Mail (inline CSS, Outlook-tauglich)
// Modus: "Run Once for All Items"
// ============================================================
const rows = $input.all().map(i => i.json).filter(r => r && r.ArtNr);

// ---------- Helfer ----------
const esc = v => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const fmt = v => {
  const n = Number(v) || 0;
  return n.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
};

const parseDE = s => {
  const m = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(String(s || ''));
  return m ? new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1])) : null;
};

const heute = new Date(); heute.setHours(0, 0, 0, 0);
const tageBis = d => d ? Math.round((d - heute) / 86400000) : null;

// ---------- Dynamische Kundengruppen-Spalten ----------
const fixed = ['ArtNr', 'Artikel', 'ISBN', 'Erscheinungstermin', 'Gesamtmenge'];
const prio = ['B2B', 'B2C'];
const groupCols = [...new Set(rows.flatMap(r => Object.keys(r)))]
  .filter(k => !fixed.includes(k))
  .sort((a, b) => {
    const pa = prio.indexOf(a) === -1 ? 99 : prio.indexOf(a);
    const pb = prio.indexOf(b) === -1 ? 99 : prio.indexOf(b);
    return pa - pb || a.localeCompare(b, 'de');
  });

// ---------- Styles ----------
const FONT   = "font-family:Arial,Helvetica,sans-serif;";
const TH     = `${FONT}font-size:12px;font-weight:bold;color:#ffffff;background-color:#1f2937;padding:10px 12px;border-bottom:2px solid #111827;white-space:nowrap;`;
const TD     = `${FONT}font-size:13px;color:#1f2937;padding:9px 12px;border-bottom:1px solid #e5e7eb;vertical-align:top;`;
const NUM    = 'text-align:right;white-space:nowrap;';
const NOWRAP = 'white-space:nowrap;';

// ---------- Leerer Bericht ----------
if (rows.length === 0) {
  return [{ json: { table: `<p style="${FONT}font-size:14px;color:#1f2937;">Aktuell liegen keine Vormerker für kommende booXperts-Titel vor.</p>`, count: 0 } }];
}

// ---------- Kopfzeile ----------
const header = `
<tr>
  <th style="${TH}text-align:left;">Titel</th>
  <th style="${TH}text-align:left;">ISBN</th>
  <th style="${TH}text-align:left;">Erscheint</th>
  <th style="${TH}${NUM}">Gesamt</th>
  ${groupCols.map(g => `<th style="${TH}${NUM}">${esc(g)}</th>`).join('')}
</tr>`;

// ---------- Datenzeilen ----------
const summen = { Gesamtmenge: 0 };
groupCols.forEach(g => summen[g] = 0);

const body = rows.map((r, idx) => {
  const bg = idx % 2 === 0 ? '#ffffff' : '#f9fafb';
  const tage = tageBis(parseDE(r.Erscheinungstermin));
  const bald = tage !== null && tage <= 30;

  summen.Gesamtmenge += Number(r.Gesamtmenge) || 0;
  groupCols.forEach(g => summen[g] += Number(r[g]) || 0);

  const etBadge = bald
    ? `<br><span style="${FONT}font-size:11px;color:#b45309;font-weight:bold;">in ${tage} Tag${tage === 1 ? '' : 'en'}</span>`
    : '';

  return `
<tr style="background-color:${bg};">
  <td style="${TD}min-width:180px;">
    <span style="font-weight:bold;">${esc(r.Artikel)}</span><br>
    <span style="font-size:11px;color:#6b7280;">${esc(r.ArtNr)}</span>
  </td>
  <td style="${TD}${NOWRAP}">${esc(r.ISBN)}</td>
  <td style="${TD}${NOWRAP}">${esc(r.Erscheinungstermin)}${etBadge}</td>
  <td style="${TD}${NUM}font-weight:bold;">${fmt(r.Gesamtmenge)}</td>
  ${groupCols.map(g => `<td style="${TD}${NUM}${(Number(r[g]) || 0) === 0 ? 'color:#9ca3af;' : ''}">${fmt(r[g])}</td>`).join('')}
</tr>`;
}).join('');

// ---------- Summenzeile ----------
const TF = `${FONT}font-size:13px;font-weight:bold;color:#111827;background-color:#e5e7eb;padding:10px 12px;border-top:2px solid #1f2937;`;
const footer = `
<tr>
  <td style="${TF}" colspan="3">Summe (${rows.length} Titel)</td>
  <td style="${TF}${NUM}">${fmt(summen.Gesamtmenge)}</td>
  ${groupCols.map(g => `<td style="${TF}${NUM}">${fmt(summen[g])}</td>`).join('')}
</tr>`;

// ---------- Mail zusammensetzen ----------
const stand = `${String(heute.getDate()).padStart(2, '0')}.${String(heute.getMonth() + 1).padStart(2, '0')}.${heute.getFullYear()}`;

const html = `
<div style="${FONT}color:#1f2937;">
  <p style="font-size:13px;color:#6b7280;margin:0 0 16px 0;">Stand ${stand} · Bestellmengen für Titel mit Erscheinungsdatum in der Zukunft</p>
  <table role="presentation" cellpadding="0" cellspacing="0" border="0"
         style="border-collapse:collapse;width:100%;max-width:1000px;border:1px solid #e5e7eb;">
    <thead>${header}</thead>
    <tbody>${body}</tbody>
    <tfoot>${footer}</tfoot>
  </table>
  <p style="font-size:11px;color:#9ca3af;margin:12px 0 0 0;">
    Gesamt = alle Aufträge · B2B = Partnerbuchhandlungen, Geschäftskunden, Händler · B2C = Endkunden ·
    <span style="color:#b45309;font-weight:bold;">orange</span> = Erscheinen in ≤ 30 Tagen
  </p>
</div>`;

return [{ json: { table: html, count: rows.length } }];

